const BASE_URL = Platform.OS === 'web' ? '/api/v1' : 'https://api.sprites.dev/v1';
const WS_BASE_URL = Platform.OS === 'web' ? 'ws://localhost:8082/v1' : 'wss://api.sprites.dev/v1';

type RNWebSocketCtor = new (
  url: string,
  protocols?: string | string[] | null,
