          break;
        }
        case 'error': {
          events.push({ type: 'error', message: readMessage(item) ?? 'Codex error' });
          break;
        }
      }
      break;
    }
    case 'turn.completed': {
      events.push({ type: 'turnCompleted' });
      break;
    }
    case 'error':
